const t = (k, ...a) => { let v = k.split(".").reduce((o, p) => (o && o[p] !== undefined ? o[p] : undefined), I18N[LANG]); if (v === undefined) v = k.split(".").reduce((o, p) => (o && o[p] !== undefined ? o[p] : undefined), I18N.zh); if (v === undefined) return k; return typeof v === "string" ? v.replace(/\{(\d+)\}/g, (_, i) => (a[i] === undefined ? "" : a[i])) : v; };
const code = (group, c) => (c === null || c === undefined || c === "") ? t("na") : (t(group + "." + c) === group + "." + c ? String(c) : t(group + "." + c));
const stateLabel = (c) => code("state", c); const riskLabel = (c) => code("risk", c); const orderLabel = (c) => code("order", c); const pkLabel = (c) => code("price_kind", c || "closed-bar"); const zoneLabel = (c) => code("zone", c); const sigLabel = (c) => code("signal", c);
/* 策略引擎 / 执行引擎的机器编码理由（如 target_changed[both|NORMAL|cap=1.00];drift 1.000 ≥ 0.1;scaled_to_cash）→ 可读文字。只在展示层转换；原文仍可在交易详情的事件原文中查看。未识别的片段保持原文。 */
const reasonText = (raw) => {
  if (raw === null || raw === undefined || raw === "") return t("na");
  const one = (tok) => {
    tok = tok.trim(); if (!tok) return ""; let m;
    if ((m = tok.match(/^target_changed\[([^|\]]*)\|([A-Z_]+)\|cap=([\d.]+)\]$/))) return t("rs_target_changed", code("rs_key", m[1]), riskLabel(m[2]), pct(Number(m[3]), 0));
    if ((m = tok.match(/^drift ([\d.]+) ≥ ([\d.]+)$/))) return t("rs_drift", m[1], m[2]);
    if (tok === "scaled_to_cash") return t("rs_scaled");
    if ((m = tok.match(/^exposure ([\d.]+) > hard_cap ([\d.]+)$/))) return t("rs_exposure", m[1], m[2]);
    if (tok === "data_quality_fault") return t("rs_dq");
    if ((m = tok.match(/^late: close (.+?) first processed at (.+?) \(> grace\)/))) return t("rs_late", tLocal(m[1]), tLocal(m[2]));
    if (/^no fresh price/.test(tok)) return t("rs_nofresh");
    if ((m = tok.match(/^engine first processed the order ([\d.]+) h after exec_after \(> grace ([^)]+)\)/))) return t("rs_expired", m[1], m[2]);
    return esc(tok.replace(/→\s*WAIT\b/g, "→ " + t("rs_wait")));
  };
  return String(raw).split(";").map(one).filter(Boolean).join("；");
};
const PAGES = ["overview", "compare", "charts", "opps", "positions", "analytics", "health", "trades", "phase13", "help"];
const $ = (s) => document.querySelector(s);
const isNil = (v) => v === null || v === undefined || Number.isNaN(v);
const fmt = (v, d = 2) => isNil(v) ? t("na") : Number(v).toLocaleString(LANG === "zh" ? "zh-CN" : "en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
const usdt = (v, d = 2) => isNil(v) ? t("na") : fmt(v, d) + " " + t("usdt");
const signed = (v, d = 2) => isNil(v) ? t("na") : (v > 0 ? "+" : "") + fmt(v, d);
const pct = (v, d = 2) => isNil(v) ? t("na") : (v * 100).toFixed(d) + "%";
const sgn = (v) => v > 0 ? "up" : v < 0 ? "down" : "";
const TZ = Intl.DateTimeFormat().resolvedOptions().timeZone; const tzLabel = () => { try { return new Intl.DateTimeFormat(LANG === "zh" ? "zh-CN" : "en-US", { timeZoneName: "short" }).formatToParts(new Date()).find((p) => p.type === "timeZoneName").value; } catch (e) { return TZ; } };
const tLocal = (s) => { if (!s) return t("na"); const d = new Date(String(s).replace(" ", "T").replace(/(\.\d+)?(\+00:00)?$/, (m, f, z) => (z ? "Z" : (String(s).endsWith("Z") ? "" : "Z")))); if (isNaN(d)) return String(s).slice(0, 16); return d.toLocaleString(LANG === "zh" ? "zh-CN" : "en-GB", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false }); };
const tDay = (s) => s ? String(s).slice(0, 10) : t("na");
const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
async function api(p) { const r = await fetch(p, { cache: "no-store" }); if (!r.ok) throw new Error(p + " → " + r.status + " " + (await r.text()).slice(0, 200)); return r.json(); }
const tag = (kind) => `<span class='tag ${kind}'>${t("tag." + kind)}</span>`; const groupTag = (g) => g === "mac_prod" ? tag("mac") : g === "shadow13" ? tag("fw") : tag("bt");
const card = (k, v, s = "", cls = "") => `<div class="card"><div class="k">${k}</div><div class="v ${cls}">${v}</div><div class="s">${s}</div></div>`;
const thead = (cols) => `<thead><tr>${cols.map((c) => `<th>${c}</th>`).join("")}</tr></thead>`;
const trendText = (tr) => !tr || !tr.trend ? t("trend_unknown") : (tr.trend.startsWith("上行") ? t("trend_up") : t("trend_down"));
const plotLayout = (title, dateAxis = false) => ({ title, margin: { t: 40, l: 60, r: 20, b: 40 }, paper_bgcolor: "#171e2e", plot_bgcolor: "#171e2e", font: { color: "#e6ebf5" }, legend: { orientation: "h" }, ...(dateAxis ? { xaxis: { tickformat: "%Y/%m/%d %H:%M", hoverformat: "%Y/%m/%d %H:%M" } } : {}) });   // 日期轴用数字格式，避免 Plotly 英文月份
