P.trades = async (m) => {
  const accs = (await api("/api/accounts")).accounts;
  m.innerHTML = `<h1>${t("tr_title")}</h1><div class="note">${t("tr_note")} ${t("tz_note", tzLabel())}。</div>
  <div class="controls"><select id="tacc"><option value="">${t("tr_all")}</option>${accs.map((a) => `<option value="${a.group}/${a.name}">${a.name}</option>`).join("")}</select><select id="tsym"><option value="">${t("tr_both")}</option><option>BTCUSDT</option><option>ETHUSDT</option></select><select id="tside"><option value="">${t("tr_side")}</option><option value="BUY">${t("signal.BUY")}</option><option value="SELL">${t("signal.SELL")}</option></select><input type="date" id="t0"><input type="date" id="t1"><input id="tq" placeholder="${t("tr_search")}"><select id="tsort"><option value="desc">${t("tr_desc")}</option><option value="asc">${t("tr_asc")}</option></select><button class="primary" id="tgo">${t("tr_query")}</button><button id="tcsv">${t("tr_csv")}</button></div><div id="tsum" class="small muted"></div><div class="tbl" id="ttbl"></div><div class="controls"><button id="tprev">${t("tr_prev")}</button><span id="tpage" class="small"></span><button id="tnext">${t("tr_next")}</button></div>`;
  let offset = 0; const limit = 100;
  const qs = () => { const q = new URLSearchParams(); const [g, n] = ($("#tacc").value || "/").split("/"); if (g) q.set("group", g); if (n) q.set("name", n); if ($("#tsym").value) q.set("symbol", $("#tsym").value); if ($("#tside").value) q.set("side", $("#tside").value); if ($("#t0").value) q.set("start", $("#t0").value); if ($("#t1").value) q.set("end", $("#t1").value); if ($("#tq").value) q.set("q", $("#tq").value); q.set("sort", $("#tsort").value); return q; };
  const load = async () => { const q = qs(); q.set("limit", limit); q.set("offset", offset); const tt = await api("/api/trades?" + q); $("#tsum").textContent = t("tr_total", tt.total); $("#tpage").textContent = `${offset + 1}–${Math.min(offset + limit, tt.total)} / ${tt.total}`;
    $("#ttbl").innerHTML = `<table>${thead(t("tr_cols"))}<tbody>${tt.rows.map((r) => `<tr class="clickable" onclick="tradeDetail('${r.group}','${r.account}','${encodeURIComponent(r.order_id)}')"><td>${groupTag(r.group)}${esc(r.account)}</td><td>${r.symbol}</td><td class="${r.side === "BUY" ? "up" : "down"}">${sigLabel(r.side)}</td><td>${tLocal(r.signal_ts)}</td><td>${tLocal(r.decision_time)}</td><td>${tLocal(r.execution_time)}</td><td>${fmt(r.fill_price)}</td><td>${fmt(r.qty, 6)}</td><td>${fmt(r.fee)}</td><td>${fmt(r.slippage_usdt)}</td><td class="${sgn(r.net_pnl)}">${isNil(r.net_pnl) ? t("na") : signed(r.net_pnl)}</td><td>${orderLabel(r.status)}</td><td>${pkLabel(r.price_kind)}${r.estimated ? "（" + t("td_est") + "）" : ""}</td><td class="wrap">${reasonText(r.signal_reason || r.reason)}</td></tr>`).join("")}</tbody></table>`; };
  $("#tgo").onclick = () => { offset = 0; load(); }; $("#tprev").onclick = () => { offset = Math.max(0, offset - limit); load(); }; $("#tnext").onclick = () => { offset += limit; load(); }; $("#tcsv").onclick = () => { window.location = "/api/trades.csv?" + qs(); }; load();
};

