/* ---------- 路由 ---------- */
function route() {
  const h = (location.hash || "#overview").slice(1); const p = P[h] ? h : "overview";
  for (const nav of ["#sidenav", "#bottomnav"]) $(nav).innerHTML = PAGES.map((k) => `<a href="#${k}" class="${k === p ? "active" : ""}">${t("nav." + k)}</a>`).join("");
  const m = $("#main"); m.innerHTML = `<p class='muted'>${t("loading")}</p>`; P[p](m).catch((e) => { m.innerHTML = `<div class="note">${t("load_fail")}${esc(e.message)}</div>`; });
}
document.documentElement.lang = LANG === "zh" ? "zh-CN" : "en";
window.addEventListener("hashchange", route); route(); header(); setInterval(header, 60000); setInterval(() => { if ((location.hash || "#overview") === "#overview") route(); }, 300000);
